effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  vec2 p = (uv - 0.5) * 2.0;
  float ar = acScreenSize.x / max(acScreenSize.y, 1.0);
  float d = mix(max(abs(p.x), abs(p.y)), length(p * vec2(ar, 1.0) / max(ar, 1.0)), roundness);
  float v = smoothstep(size, size + softness, d) * amount * mixAmt;
  vec3 col = mix(c, vigColor.rgb, clamp(v, 0.0, 1.0));
  gl_FragColor = vec4(col * a, a);
}
